ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS is_ai_generated boolean NOT NULL DEFAULT false;

UPDATE public.profiles
SET is_ai_generated = true
WHERE id IN (
  'demo-ai-ren',
  'demo-ai-ao',
  'demo-ai-mio',
  'demo-ai-riku',
  'demo-ai-kota',
  'demo-ai-nagi'
)
AND is_ai_generated IS DISTINCT FROM true;

COMMENT ON COLUMN public.profiles.is_ai_generated IS
  'Internal marker for fictional profiles generated by Lime2 automation; intentionally excluded from public client column grants.';
